1	package com.example.starter.plan.service;
2	
3	import com.example.starter.plan.model.DayPlan;
4	import com.example.starter.plan.model.Occupancy;
5	import com.example.starter.plan.model.PlanStatus;
6	import com.example.starter.plan.model.PublishedSlot;
7	import com.example.starter.plan.model.RescheduleLink;
8	import com.example.starter.plan.repo.IdempotencyRepository;
9	import com.example.starter.plan.repo.PlanRepository;
10	import com.example.starter.plan.web.ApiException;
11	import com.example.starter.plan.web.dto.CreatePlanRequest;
12	import com.example.starter.plan.web.dto.OccupancyRequest;
13	import com.example.starter.plan.web.dto.OccupancyView;
14	import com.example.starter.plan.web.dto.PlanResponse;
15	import com.example.starter.plan.web.dto.PublishedSlotView;
16	import com.example.starter.plan.web.dto.RescheduleChainItem;
17	import com.example.starter.plan.web.dto.RescheduleChainResponse;
18	import com.example.starter.plan.web.dto.RescheduleRequest;
19	import com.example.starter.plan.web.dto.RescheduleResponse;
20	import com.example.starter.plan.web.dto.UpdateOccupanciesRequest;
21	import com.fasterxml.jackson.databind.ObjectMapper;
22	import java.nio.charset.StandardCharsets;
23	import java.security.MessageDigest;
24	import java.security.NoSuchAlgorithmException;
25	import java.time.Instant;
26	import java.time.LocalDate;
27	import java.time.ZoneId;
28	import java.util.ArrayList;
29	import java.util.Collections;
30	import java.util.Comparator;
31	import java.util.LinkedHashMap;
32	import java.util.List;
33	import java.util.Map;
34	import java.util.Optional;
35	import java.util.TreeSet;
36	import org.springframework.dao.DuplicateKeyException;
37	import org.springframework.http.HttpStatus;
38	import org.springframework.stereotype.Service;
39	import org.springframework.transaction.PlatformTransactionManager;
40	import org.springframework.transaction.support.TransactionTemplate;
41	
42	/**
43	 * 铁路走廊日计划核心业务：草稿创建/整体替换、发布、取消、原子改签与查询。
44	 *
45	 * <p>并发与幂等约定：写操作按 (操作类型, requestKey) 幂等，同键同参重放返回首次成功结果，
46	 * 同键不同参返回 409；发布与改签经全局发布锁串行化，同一计划的更新/发布/取消/改签经行锁按事务提交顺序生效；
47	 * 仅成功结果写入幂等记录，失败（含 422 时隙冲突）不缓存、可修正后重试。
48	 */
49	@Service
50	public class PlanService {
51	
52	    /** 运营日解释时区。 */
53	    public static final ZoneId OPERATION_ZONE = ZoneId.of("Asia/Shanghai");
54	
55	    private static final String OP_CREATE = "CREATE";
56	    private static final String OP_UPDATE = "UPDATE";
57	    private static final String OP_PUBLISH = "PUBLISH";
58	    private static final String OP_CANCEL = "CANCEL";
59	    private static final String OP_RESCHEDULE = "RESCHEDULE";
60	
61	    private final PlanRepository planRepo;
62	    private final IdempotencyRepository idemRepo;
63	    private final ObjectMapper objectMapper;
64	    private final TransactionTemplate tx;
65	
66	    public PlanService(PlanRepository planRepo, IdempotencyRepository idemRepo,
67	                       ObjectMapper objectMapper, PlatformTransactionManager txManager) {
68	        this.planRepo = planRepo;
69	        this.idemRepo = idemRepo;
70	        this.objectMapper = objectMapper;
71	        this.tx = new TransactionTemplate(txManager);
72	    }
73	
74	    /**
75	     * 创建草稿计划（版本 1，状态 DRAFT）。
76	     */
77	    public PlanResponse createDraft(CreatePlanRequest req) {
78	        validateOccupancyParams(req.occupancies());
79	        validateWithinOperationDay(req.occupancies(), req.opDate());
80	        String hash = hashCreate(req);
81	        Optional<PlanResponse> replay = replayIfPresent(OP_CREATE, req.requestKey(), hash);
82	        if (replay.isPresent()) {
83	            return replay.get();
84	        }
85	        try {
86	            return tx.execute(status -> {
87	                if (planRepo.findByKey(req.scheduleKey()).isPresent()) {
88	                    throw conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在: " + req.scheduleKey());
89	                }
90	                long now = System.currentTimeMillis();
91	                long planId = planRepo.insertPlan(req.scheduleKey(), req.opDate(), PlanStatus.DRAFT, now);
92	                planRepo.insertOccupancies(planId, toOccupancies(planId, req.occupancies()));
93	                PlanResponse response = loadPlan(req.scheduleKey());
94	                idemRepo.insert(OP_CREATE, req.requestKey(), hash, toJson(response), now);
95	                return response;
96	            });
97	        } catch (DuplicateKeyException e) {
98	            return resolveDuplicate(OP_CREATE, req.requestKey(), hash);
99	        }
100	    }
101	
102	    /**
103	     * 整体替换草稿占用清单，版本加一；仅 DRAFT 可改，expectedVersion 必须匹配。
104	     */
105	    public PlanResponse replaceOccupancies(String scheduleKey, UpdateOccupanciesRequest req) {
106	        validateOccupancyParams(req.occupancies());
107	        String hash = hashUpdate(scheduleKey, req);
108	        Optional<PlanResponse> replay = replayIfPresent(OP_UPDATE, req.requestKey(), hash);
109	        if (replay.isPresent()) {
110	            return replay.get();
111	        }
112	        try {
113	            return tx.execute(status -> {
114	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
115	                        .orElseThrow(() -> notFound(scheduleKey));
116	                if (plan.status() != PlanStatus.DRAFT) {
117	                    throw conflict("PLAN_STATE_CONFLICT",
118	                            "仅草稿可修改占用，当前状态: " + plan.status());
119	                }
120	                if (req.expectedVersion() != plan.version()) {
121	                    throw conflict("VERSION_CONFLICT",
122	                            "expectedVersion=" + req.expectedVersion() + " 与当前版本 " + plan.version() + " 不一致");
123	                }
124	                validateWithinOperationDay(req.occupancies(), plan.opDate());
125	                long now = System.currentTimeMillis();
126	                planRepo.replaceOccupancies(plan.id(), toOccupancies(plan.id(), req.occupancies()));
127	                planRepo.updateVersionAndStatus(plan.id(), plan.version() + 1, PlanStatus.DRAFT, now);
128	                PlanResponse response = loadPlan(scheduleKey);
129	                idemRepo.insert(OP_UPDATE, req.requestKey(), hash, toJson(response), now);
130	                return response;
131	            });
132	        } catch (DuplicateKeyException e) {
133	            return resolveDuplicate(OP_UPDATE, req.requestKey(), hash);
134	        }
135	    }
136	
137	    /**
138	     * 发布计划：全局发布锁内原子校验本计划列车重叠与跨计划区段重叠，
139	     * 任一冲突则整张计划保持草稿并抛出 422（携带冲突区段与计划）。
140	     */
141	    public PlanResponse publish(String scheduleKey, String requestKey) {
142	        String hash = hashAction(OP_PUBLISH, scheduleKey);
143	        Optional<PlanResponse> replay = replayIfPresent(OP_PUBLISH, requestKey, hash);
144	        if (replay.isPresent()) {
145	            return replay.get();
146	        }
147	        try {
148	            return tx.execute(status -> {
149	                planRepo.acquirePublishLock();
150	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
151	                        .orElseThrow(() -> notFound(scheduleKey));
152	                if (plan.status() != PlanStatus.DRAFT) {
153	                    throw conflict("PLAN_STATE_CONFLICT",
154	                            "仅草稿可发布，当前状态: " + plan.status());
155	                }
156	                List<Occupancy> occupancies = planRepo.findOccupancies(plan.id());
157	                List<Map<String, Object>> conflicts = new ArrayList<>();
158	                conflicts.addAll(findTrainOverlaps(scheduleKey, occupancies));
159	                conflicts.addAll(findSectionConflicts(plan, occupancies, List.of(plan.id())));
160	                if (!conflicts.isEmpty()) {
161	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT",
162	                            "存在时隙冲突，计划保持草稿", conflicts);
163	                }
164	                long now = System.currentTimeMillis();
165	                planRepo.updateStatus(plan.id(), PlanStatus.PUBLISHED, now);
166	                PlanResponse response = loadPlan(scheduleKey);
167	                idemRepo.insert(OP_PUBLISH, requestKey, hash, toJson(response), now);
168	                return response;
169	            });
170	        } catch (DuplicateKeyException e) {
171	            return resolveDuplicate(OP_PUBLISH, requestKey, hash);
172	        }
173	    }
174	
175	    /**
176	     * 取消已发布计划：时隙立即释放，历史计划与占用保留不改写。
177	     */
178	    public PlanResponse cancel(String scheduleKey, String requestKey) {
179	        String hash = hashAction(OP_CANCEL, scheduleKey);
180	        Optional<PlanResponse> replay = replayIfPresent(OP_CANCEL, requestKey, hash);
181	        if (replay.isPresent()) {
182	            return replay.get();
183	        }
184	        try {
185	            return tx.execute(status -> {
186	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
187	                        .orElseThrow(() -> notFound(scheduleKey));
188	                if (plan.status() != PlanStatus.PUBLISHED) {
189	                    throw conflict("PLAN_STATE_CONFLICT",
190	                            "仅已发布计划可取消，当前状态: " + plan.status());
191	                }
192	                long now = System.currentTimeMillis();
193	                planRepo.updateStatus(plan.id(), PlanStatus.CANCELLED, now);
194	                PlanResponse response = loadPlan(scheduleKey);
195	                idemRepo.insert(OP_CANCEL, requestKey, hash, toJson(response), now);
196	                return response;
197	            });
198	        } catch (DuplicateKeyException e) {
199	            return resolveDuplicate(OP_CANCEL, requestKey, hash);
200	        }
201	    }
202	
203	    /**
204	     * 原子改签：全局发布锁内校验新草稿（列车内部重叠与跨计划区段冲突，仅排除旧计划占用），
205	     * 通过后同一事务取消旧计划、发布新计划并追加不可变前后继关联。
206	     * 任一步失败整体回滚：旧计划仍发布、新计划仍草稿，版本、占用与关联均不改变。
207	     */
208	    public RescheduleResponse reschedule(String oldScheduleKey, RescheduleRequest req) {
209	        if (oldScheduleKey.equals(req.newScheduleKey())) {
210	            throw badRequest("新旧计划必须不同: " + oldScheduleKey);
211	        }
212	        String hash = hashReschedule(oldScheduleKey, req);
213	        Optional<RescheduleResponse> replay =
214	                replayIfPresent(OP_RESCHEDULE, req.requestKey(), hash, RescheduleResponse.class);
215	        if (replay.isPresent()) {
216	            return replay.get();
217	        }
218	        try {
219	            return tx.execute(status -> {
220	                planRepo.acquirePublishLock();
221	                DayPlan oldPlan = planRepo.findByKeyForUpdate(oldScheduleKey)
222	                        .orElseThrow(() -> notFound(oldScheduleKey));
223	                DayPlan newPlan = planRepo.findByKeyForUpdate(req.newScheduleKey())
224	                        .orElseThrow(() -> notFound(req.newScheduleKey()));
225	                if (oldPlan.status() != PlanStatus.PUBLISHED) {
226	                    throw conflict("PLAN_STATE_CONFLICT",
227	                            "仅已发布计划可改签，旧计划当前状态: " + oldPlan.status());
228	                }
229	                if (newPlan.status() != PlanStatus.DRAFT) {
230	                    throw conflict("PLAN_STATE_CONFLICT",
231	                            "改签新计划必须为草稿，当前状态: " + newPlan.status());
232	                }
233	                if (req.expectedOldVersion() != oldPlan.version()) {
234	                    throw conflict("VERSION_CONFLICT",
235	                            "expectedOldVersion=" + req.expectedOldVersion()
236	                                    + " 与旧计划当前版本 " + oldPlan.version() + " 不一致");
237	                }
238	                if (req.expectedNewVersion() != newPlan.version()) {
239	                    throw conflict("VERSION_CONFLICT",
240	                            "expectedNewVersion=" + req.expectedNewVersion()
241	                                    + " 与新计划当前版本 " + newPlan.version() + " 不一致");
242	                }
243	                if (!oldPlan.opDate().equals(newPlan.opDate())) {
244	                    throw conflict("OP_DATE_MISMATCH",
245	                            "新旧计划运营日必须相同: 旧=" + oldPlan.opDate() + " 新=" + newPlan.opDate());
246	                }
247	                if (planRepo.findLinkByPredecessor(oldPlan.id()).isPresent()) {
248	                    throw conflict("LINK_CONFLICT", "旧计划已存在直接后继: " + oldScheduleKey);
249	                }
250	                if (planRepo.findLinkBySuccessor(newPlan.id()).isPresent()) {
251	                    throw conflict("LINK_CONFLICT", "新计划已存在直接前驱: " + req.newScheduleKey());
252	                }
253	                List<Occupancy> occupancies = planRepo.findOccupancies(newPlan.id());
254	                List<Map<String, Object>> conflicts = new ArrayList<>();
255	                conflicts.addAll(findTrainOverlaps(req.newScheduleKey(), occupancies));
256	                // 仅排除旧计划与自身占用，第三方已发布计划照常参与冲突裁决
257	                conflicts.addAll(findSectionConflicts(newPlan, occupancies,
258	                        List.of(newPlan.id(), oldPlan.id())));
259	                if (!conflicts.isEmpty()) {
260	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT",
261	                            "新草稿存在时隙冲突，改签未生效", conflicts);
262	                }
263	                long now = System.currentTimeMillis();
264	                planRepo.updateStatus(oldPlan.id(), PlanStatus.CANCELLED, now);
265	                planRepo.updateStatus(newPlan.id(), PlanStatus.PUBLISHED, now);
266	                planRepo.insertRescheduleLink(oldPlan.id(), newPlan.id(), now);
267	                RescheduleResponse response = new RescheduleResponse(
268	                        loadPlan(oldScheduleKey), loadPlan(req.newScheduleKey()));
269	                idemRepo.insert(OP_RESCHEDULE, req.requestKey(), hash, toJson(response), now);
270	                return response;
271	            });
272	        } catch (DuplicateKeyException e) {
273	            return replayIfPresent(OP_RESCHEDULE, req.requestKey(), hash, RescheduleResponse.class)
274	                    .orElseThrow(() -> conflict("LINK_CONFLICT", "改签前后继关联冲突"));
275	        }
276	    }
277	
278	    /**
279	     * 查询包含指定计划在内的完整有序改签链（从最前驱到最后继）；
280	     * 无改签历史的计划链中仅含自身。计划不存在返回 404。
281	     */
282	    public RescheduleChainResponse getRescheduleChain(String scheduleKey) {
283	        DayPlan plan = planRepo.findByKey(scheduleKey)
284	                .orElseThrow(() -> notFound(scheduleKey));
285	        List<DayPlan> predecessors = new ArrayList<>();
286	        DayPlan cursor = plan;
287	        while (true) {
288	            Optional<RescheduleLink> link = planRepo.findLinkBySuccessor(cursor.id());
289	            if (link.isEmpty()) {
290	                break;
291	            }
292	            cursor = planRepo.findById(link.get().predecessorPlanId())
293	                    .orElseThrow(() -> new IllegalStateException("改签链前驱缺失: " + link.get()));
294	            predecessors.add(cursor);
295	        }
296	        Collections.reverse(predecessors);
297	        List<DayPlan> chain = new ArrayList<>(predecessors);
298	        chain.add(plan);
299	        cursor = plan;
300	        while (true) {
301	            Optional<RescheduleLink> link = planRepo.findLinkByPredecessor(cursor.id());
302	            if (link.isEmpty()) {
303	                break;
304	            }
305	            cursor = planRepo.findById(link.get().successorPlanId())
306	                    .orElseThrow(() -> new IllegalStateException("改签链后继缺失: " + link.get()));
307	            chain.add(cursor);
308	        }
309	        List<RescheduleChainItem> items = chain.stream()
310	                .map(p -> new RescheduleChainItem(p.scheduleKey(), p.opDate(), p.version(),
311	                        p.status().name()))
312	                .toList();
313	        return new RescheduleChainResponse(scheduleKey, items);
314	    }
315	
316	    /**
317	     * 按计划业务键查询明细（含历史占用），不存在返回 404。
318	     */
319	    public PlanResponse getPlan(String scheduleKey) {
320	        if (planRepo.findByKey(scheduleKey).isEmpty()) {
321	            throw notFound(scheduleKey);
322	        }
323	        return loadPlan(scheduleKey);
324	    }
325	
326	    /**
327	     * 查询指定运营日与区段上当前已发布的生效时隙。
328	     */
329	    public List<PublishedSlotView> getPublishedSlots(LocalDate opDate, String sectionId) {
330	        return planRepo.findPublishedSlots(opDate, List.of(sectionId), List.of(-1L)).stream()
331	                .map(s -> new PublishedSlotView(s.scheduleKey(), s.trainNo(), s.sectionId(),
332	                        s.startUtc(), s.endUtc()))
333	                .toList();
334	    }
335	
336	    // ---------- 内部实现 ----------
337	
338	    private PlanResponse loadPlan(String scheduleKey) {
339	        DayPlan plan = planRepo.findByKey(scheduleKey)
340	                .orElseThrow(() -> notFound(scheduleKey));
341	        List<OccupancyView> views = planRepo.findOccupancies(plan.id()).stream()
342	                .map(o -> new OccupancyView(o.trainNo(), o.sectionId(), o.startUtc(), o.endUtc()))
343	                .toList();
344	        return new PlanResponse(plan.scheduleKey(), plan.opDate(), plan.version(),
345	                plan.status().name(), views);
346	    }
347	
348	    private List<Occupancy> toOccupancies(long planId, List<OccupancyRequest> requests) {
349	        List<Occupancy> result = new ArrayList<>(requests.size());
350	        for (int i = 0; i < requests.size(); i++) {
351	            OccupancyRequest r = requests.get(i);
352	            result.add(new Occupancy(0L, planId, i, r.trainNo(), r.sectionId(), r.startUtc(), r.endUtc()));
353	        }
354	        return result;
355	    }
356	
357	    /**
358	     * 参数级校验：结束必须晚于开始，且起止落在同一 Asia/Shanghai 日历日内。
359	     */
360	    private void validateOccupancyParams(List<OccupancyRequest> occupancies) {
361	        for (int i = 0; i < occupancies.size(); i++) {
362	            OccupancyRequest o = occupancies.get(i);
363	            if (!o.endUtc().isAfter(o.startUtc())) {
364	                throw badRequest("第 " + i + " 条占用结束时刻必须晚于开始时刻");
365	            }
366	            LocalDate startDay = o.startUtc().atZone(OPERATION_ZONE).toLocalDate();
367	            LocalDate endDay = o.endUtc().minusNanos(1).atZone(OPERATION_ZONE).toLocalDate();
368	            if (!startDay.equals(endDay)) {
369	                throw badRequest("第 " + i + " 条占用必须落在同一运营日（Asia/Shanghai）内");
370	            }
371	        }
372	    }
373	
374	    /**
375	     * 占用必须落在计划运营日内：[start, end) 完全包含于运营日 [dayStart, dayEnd)。
376	     */
377	    private void validateWithinOperationDay(List<OccupancyRequest> occupancies, LocalDate opDate) {
378	        Instant dayStart = opDate.atStartOfDay(OPERATION_ZONE).toInstant();
379	        Instant dayEnd = opDate.plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
380	        for (int i = 0; i < occupancies.size(); i++) {
381	            OccupancyRequest o = occupancies.get(i);
382	            if (o.startUtc().isBefore(dayStart) || o.endUtc().isAfter(dayEnd)) {
383	                throw badRequest("第 " + i + " 条占用不在运营日 " + opDate + "（Asia/Shanghai）内");
384	            }
385	        }
386	    }
387	
388	    /**
389	     * 本计划内同一列车的重叠占用检测（左闭右开，相邻合法）。
390	     */
391	    private List<Map<String, Object>> findTrainOverlaps(String scheduleKey, List<Occupancy> occupancies) {
392	        List<Map<String, Object>> conflicts = new ArrayList<>();
393	        Map<String, List<Occupancy>> byTrain = new LinkedHashMap<>();
394	        for (Occupancy o : occupancies) {
395	            byTrain.computeIfAbsent(o.trainNo(), k -> new ArrayList<>()).add(o);
396	        }
397	        byTrain.forEach((trainNo, list) -> {
398	            List<Occupancy> sorted = list.stream()
399	                    .sorted(Comparator.comparing(Occupancy::startUtc)).toList();
400	            for (int i = 1; i < sorted.size(); i++) {
401	                Occupancy prev = sorted.get(i - 1);
402	                Occupancy cur = sorted.get(i);
403	                if (cur.startUtc().isBefore(prev.endUtc())) {
404	                    Map<String, Object> detail = new LinkedHashMap<>();
405	                    detail.put("type", "TRAIN_OVERLAP");
406	                    detail.put("scheduleKey", scheduleKey);
407	                    detail.put("trainNo", trainNo);
408	                    detail.put("sectionId", cur.sectionId());
409	                    detail.put("startUtc", cur.startUtc().toString());
410	                    detail.put("endUtc", cur.endUtc().toString());
411	                    conflicts.add(detail);
412	                }
413	            }
414	        });
415	        return conflicts;
416	    }
417	
418	    /**
419	     * 与其他已发布计划在同日期、同区段上的重叠检测（左闭右开，相邻合法）。
420	     *
421	     * @param excludePlanIds 检测时排除的计划 id（发布为自身；改签为新旧两个计划）
422	     */
423	    private List<Map<String, Object>> findSectionConflicts(DayPlan plan, List<Occupancy> occupancies,
424	                                                           List<Long> excludePlanIds) {
425	        List<String> sectionIds = occupancies.stream()
426	                .map(Occupancy::sectionId)
427	                .collect(java.util.stream.Collectors.toCollection(TreeSet::new))
428	                .stream().toList();
429	        List<PublishedSlot> published = planRepo.findPublishedSlots(plan.opDate(), sectionIds,
430	                excludePlanIds);
431	        List<Map<String, Object>> conflicts = new ArrayList<>();
432	        for (Occupancy o : occupancies) {
433	            for (PublishedSlot slot : published) {
434	                if (!o.sectionId().equals(slot.sectionId())) {
435	                    continue;
436	                }
437	                boolean overlap = o.startUtc().isBefore(slot.endUtc())
438	                        && slot.startUtc().isBefore(o.endUtc());
439	                if (overlap) {
440	                    Map<String, Object> detail = new LinkedHashMap<>();
441	                    detail.put("type", "SECTION_CONFLICT");
442	                    detail.put("sectionId", o.sectionId());
443	                    detail.put("scheduleKey", plan.scheduleKey());
444	                    detail.put("conflictingScheduleKey", slot.scheduleKey());
445	                    detail.put("trainNo", o.trainNo());
446	                    detail.put("startUtc", o.startUtc().toString());
447	                    detail.put("endUtc", o.endUtc().toString());
448	                    conflicts.add(detail);
449	                }
450	            }
451	        }
452	        return conflicts;
453	    }
454	
455	    /**
456	     * 幂等重放：存在记录且参数一致返回首次结果；参数不一致抛 409。
457	     */
458	    private Optional<PlanResponse> replayIfPresent(String opType, String requestKey, String hash) {
459	        return replayIfPresent(opType, requestKey, hash, PlanResponse.class);
460	    }
461	
462	    /**
463	     * 幂等重放（泛型）：存在记录且参数一致返回首次结果；参数不一致抛 409。
464	     */
465	    private <T> Optional<T> replayIfPresent(String opType, String requestKey, String hash,
466	                                            Class<T> type) {
467	        return idemRepo.find(opType, requestKey).map(record -> {
468	            if (!record.requestHash().equals(hash)) {
469	                throw conflict("IDEMPOTENT_KEY_REUSED",
470	                        "requestKey 已用于其他参数: " + requestKey);
471	            }
472	            return fromJson(record.responseJson(), type);
473	        });
474	    }
475	
476	    /**
477	     * 并发下唯一键冲突后的裁决：若为同键重放返回首次结果，否则说明 scheduleKey 冲突。
478	     */
479	    private PlanResponse resolveDuplicate(String opType, String requestKey, String hash) {
480	        return replayIfPresent(opType, requestKey, hash)
481	                .orElseThrow(() -> conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在"));
482	    }
483	
484	    private String hashCreate(CreatePlanRequest req) {
485	        StringBuilder sb = new StringBuilder(OP_CREATE).append('\n')
486	                .append(req.scheduleKey()).append('\n').append(req.opDate());
487	        appendOccupancies(sb, req.occupancies());
488	        return sha256(sb.toString());
489	    }
490	
491	    private String hashUpdate(String scheduleKey, UpdateOccupanciesRequest req) {
492	        StringBuilder sb = new StringBuilder(OP_UPDATE).append('\n')
493	                .append(scheduleKey).append('\n').append(req.expectedVersion());
494	        appendOccupancies(sb, req.occupancies());
495	        return sha256(sb.toString());
496	    }
497	
498	    private String hashAction(String opType, String scheduleKey) {
499	        return sha256(opType + '\n' + scheduleKey);
500	    }
501	
502	    private String hashReschedule(String oldScheduleKey, RescheduleRequest req) {
503	        return sha256(OP_RESCHEDULE + '\n' + oldScheduleKey + '\n' + req.newScheduleKey()
504	                + '\n' + req.expectedOldVersion() + '\n' + req.expectedNewVersion());
505	    }
506	
507	    private void appendOccupancies(StringBuilder sb, List<OccupancyRequest> occupancies) {
508	        for (OccupancyRequest o : occupancies) {
509	            sb.append('\n').append(o.trainNo()).append('|').append(o.sectionId()).append('|')
510	                    .append(o.startUtc().toEpochMilli()).append('|').append(o.endUtc().toEpochMilli());
511	        }
512	    }
513	
514	    private String sha256(String text) {
515	        try {
516	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
517	            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
518	            StringBuilder hex = new StringBuilder(hashed.length * 2);
519	            for (byte b : hashed) {
520	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
521	                hex.append(Character.forDigit(b & 0xF, 16));
522	            }
523	            return hex.toString();
524	        } catch (NoSuchAlgorithmException e) {
525	            throw new IllegalStateException(e);
526	        }
527	    }
528	
529	    private String toJson(Object response) {
530	        try {
531	            return objectMapper.writeValueAsString(response);
532	        } catch (Exception e) {
533	            throw new IllegalStateException("响应序列化失败", e);
534	        }
535	    }
536	
537	    private <T> T fromJson(String json, Class<T> type) {
538	        try {
539	            return objectMapper.readValue(json, type);
540	        } catch (Exception e) {
541	            throw new IllegalStateException("幂等响应反序列化失败", e);
542	        }
543	    }
544	
545	    private ApiException badRequest(String message) {
546	        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
547	    }
548	
549	    private ApiException notFound(String scheduleKey) {
550	        return new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
551	                "计划不存在: " + scheduleKey);
552	    }
553	
554	    private ApiException conflict(String code, String message) {
555	        return new ApiException(HttpStatus.CONFLICT, code, message);
556	    }
557	}
