39	
40	    // ---------- 主流程 ----------
41	
42	    @Test
43	    void createDraftThenGetDetail() throws Exception {
44	        String scheduleKey = key("SCH");
45	        MvcResult created = mvc.perform(post("/api/v1/plans")
46	                        .contentType(MediaType.APPLICATION_JSON)
47	                        .content(createBody(key("REQ"), scheduleKey,
48	                                occ("G1", key("SEC"), iso(8), iso(9)),
49	                                occ("G2", key("SEC"), iso(9), iso(10)))))
50	                .andExpect(status().isCreated())
51	                .andReturn();
52	        JsonNode body = read(created);
