54	        assertThat(body.get("version").asInt()).isEqualTo(1);
55	        assertThat(body.get("status").asText()).isEqualTo("DRAFT");
56	        assertThat(body.get("occupancies")).hasSize(2);
57	        assertThat(body.get("occupancies").get(0).get("startUtc").asText())
58	                .isEqualTo(iso(8));
59	
60	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", scheduleKey))
61	                .andExpect(status().isOk()).andReturn();
62	        assertThat(read(detail)).isEqualTo(body);
