67	        String scheduleKey = key("SCH");
68	        createPlan(scheduleKey, occ("G1", key("SEC"), iso(8), iso(9)));
69	
70	        MvcResult updated = mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
71	                        .contentType(MediaType.APPLICATION_JSON)
72	                        .content(updateBody(key("REQ"), 1,
