77	    @Test
78	    void concurrentCreateSameKeyReturnsFirstResult() throws Exception {
79	        String scheduleKey = key("SCH");
80	        String requestKey = key("REQ");
81	        String section = key("SEC");
82	        int threads = 4;
83	
84	        List<OccupancyRequest> occupancies = List.of(occ(section, 8, 9));
85	        List<Callable<PlanResponse>> tasks = new ArrayList<>();
86	        for (int i = 0; i < threads; i++) {
87	            tasks.add(() -> service.createDraft(new CreatePlanRequest(
88	                    requestKey, scheduleKey, DAY, occupancies)));
89	        }
90	        ExecutorService pool = Executors.newFixedThreadPool(threads);
91	        CountDownLatch ready = new CountDownLatch(threads);
92	        CountDownLatch go = new CountDownLatch(1);
93	        List<Future<PlanResponse>> futures = tasks.stream()
94	                .map(t -> pool.submit(() -> {
95	                    ready.countDown();
96	                    go.await();
97	                    return t.call();
98	                })).toList();
99	        ready.await();
100	        go.countDown();
101	        List<PlanResponse> responses = new ArrayList<>();
102	        for (Future<PlanResponse> f : futures) {
103	            responses.add(f.get(30, TimeUnit.SECONDS));
104	        }
105	        pool.shutdown();
106	
107	        // 全部返回首次结果，且库里只有一张计划
108	        assertThat(responses).allMatch(r -> r.equals(responses.get(0)));
109	        Integer count = jdbc.queryForObject(
110	                "SELECT COUNT(*) FROM rail_day_plan WHERE schedule_key = ?",
111	                Integer.class, scheduleKey);
112	        assertThat(count).isEqualTo(1);
113	    }
