115	    @Test
116	    void concurrentUpdateAndPublishApplyInCommitOrder() throws Exception {
117	        String section = key("SEC");
118	        String scheduleKey = key("SCH");
119	        createDraft(scheduleKey, section, 8, 9);
120	
121	        List<Outcome> outcomes = runConcurrently(List.of(
122	                () -> {
123	                    try {
124	                        service.replaceOccupancies(scheduleKey, new UpdateOccupanciesRequest(
125	                                key("REQ"), 1, List.of(occ(section, 10, 11))));
126	                        return Outcome.OK;
127	                    } catch (ApiException e) {
128	                        // 发布先提交时更新应得 409 状态冲突
129	                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT);
130	                        return Outcome.CONFLICT;
131	                    }
132	                },
133	                () -> {
134	                    service.publish(scheduleKey, key("REQ"));
135	                    return Outcome.OK;
136	                }));
137	
138	        // 发布必须成功；更新要么先于发布成功（版本 2），要么因已发布而 409（版本 1）
139	        PlanResponse plan = service.getPlan(scheduleKey);
140	        assertThat(plan.status()).isEqualTo("PUBLISHED");
141	        if (outcomes.get(0) == Outcome.OK) {
142	            assertThat(plan.version()).isEqualTo(2);
143	            assertThat(plan.occupancies().get(0).startUtc()).isEqualTo(at(10));
144	        } else {
145	            assertThat(plan.version()).isEqualTo(1);
146	            assertThat(plan.occupancies().get(0).startUtc()).isEqualTo(at(8));
147	        }
