151	    void cancelDoesNotReleaseOtherPlansSlots() {
152	        String section = key("SEC");
153	        String planA = key("SCH");
154	        String planB = key("SCH");
155	        createDraft(planA, section, 8, 9);
156	        createDraft(planB, section, 9, 10);
