        String hash = hashTrain(OP_TRAIN_CREATE, trainNo, req.operator(), null,
                req.axleWeightsKg());
        Optional<TrainAxleProfileResponse> replay =
                replayIfPresent(OP_TRAIN_CREATE, req.requestId(), hash);
