    // ---------- 精确求和：边界相等放行，long 溢出不得放行 ----------

    @Test
    void windowSumExactBoundaryAndNoLongOverflow() throws Exception {
        // 三窗和恰等于上限：合法
        String exactTrain = key("TRAIN");
