                "SELECT seq, weight_kg, profile_version FROM rail_plan_frozen_axle"
                        + " WHERE plan_id = (SELECT id FROM rail_day_plan WHERE schedule_key = ?)"
                        + " ORDER BY seq", scheduleKey);
        assertThat(frozenAxles).hasSize(4);
        assertThat(frozenAxles.get(1).get("weight_kg")).isEqualTo(8000L);
        assertThat(frozenAxles.get(0).get("profile_version")).isEqualTo(1);
        List<Map<String, Object>> frozenSections = jdbc.queryForList(
                "SELECT profile_version, single_axle_limit_kg, window3_limit_kg"
                        + " FROM rail_plan_frozen_section"
                        + " WHERE plan_id = (SELECT id FROM rail_day_plan WHERE schedule_key = ?)",
