                "SELECT seq, weight_kg, profile_version FROM rail_plan_frozen_axle"
                        + " WHERE plan_id = (SELECT id FROM rail_day_plan WHERE schedule_key = ?)"
                        + " ORDER BY seq", scheduleKey);
        assertThat(frozenAfter).isEqualTo(frozenAxles);
    }

