        MvcResult updated = mvc.perform(put("/api/v1/train-axle-profiles/{trainNo}", train)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(trainUpdateBody(key("RID"), "dispatcher-2", 1,
